{"output": "def transform(grid):
    h,w=len(grid),len(grid[0]); vals=[v for row in grid for v in row]; bg=max(set(vals),key=vals.count); out=[row[:] for row in grid]
    left=[r for r in range(h) if grid[r][0]!=bg]
    has_left_run=bool(left)
    # Left bar and sparse seeds: horizontal rays reach leftward; rows above
    # the first seed are filled with the seed color.
    dots=[(r,c,grid[r][c]) for r in range(h) for c in range(1,w-1) if grid[r][c] not in (bg,0)]
    if left and dots:
        paint=dots[0][2]
        for r,c,v in dots:
            out[r][c]=4
            for x in range(c-1,0,-1):
                if grid[r][x] in (bg,0):out[r][x]=v
        # The right-edge 0 run encodes a complete horizontal band above the
        # nearby separator row; the left zero run is an independent boundary.
        for r in range(h):
            if grid[r][w-1]==0:
                for c in range(1,w-1):
                    if grid[r][c]==bg:out[r][c]=paint
        # Rows above the first seed are also inside the stripe panel only when
        # the opposite edge sentinel marks that row.
        first=min(y for y,x,v in dots)
        for r in range(first):
            if grid[r][w-1]==0:
                for c in range(1,w-1):
                    if grid[r][c]==bg:out[r][c]=paint
        return out
    # Else, independently project interior seeds inward from the nearest bar.
    for r in range(h):
        for c in range(1,w-1):
            v=grid[r][c]
            if v==bg or v==0:continue
            out[r][c]=4
            dx=-1 if left else 1
            x=c+dx
            while 1<=x<w-1 and grid[r][x]==bg:out[r][x]=v;x+=dx
    return out

